const req = $('Dashboard: quality action').first().json.body || {};
const p = req.params || {};
const who = $('Verify caller').first().json;
const role = who.role;
const actor = 'dashboard:' + who.userId;
const senior = ['admin', 'manager'].includes(role);
const bad = (error, code = 400) => [{ json: { valid: false, code, error } }];
const ok = (rpc, body, note) => [{ json: { valid: true, rpc, body, note } }];
const s = (v) => String(v == null ? '' : v).trim();
const num = (v) => (s(v) === '' ? null : Number(v));
switch (req.action) {
  case 'record_check':
    if (!p.check_id && !p.order_id) return bad('Choose an order, or the pending check you are completing.');
    return ok('flow_qc_record_check', { p_check: p.check_id || null, p_order: p.order_id || null, p_gate: s(p.gate) || null, p_checked: num(p.units_checked), p_failed: num(p.units_failed) ?? 0, p_results: Array.isArray(p.results) ? p.results : [], p_defect: s(p.defect_type) || null, p_cause: s(p.cause) || null, p_notes: s(p.notes) || null, p_evidence: Array.isArray(p.evidence) ? p.evidence : [], p_line: p.order_line_id || null, p_movement: s(p.movement) || null, p_checkpoint: num(p.checkpoint_pct), p_actor: actor }, 'Check recorded.');
  case 'open_rework':
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_qc_open_rework', { p_order: p.order_id, p_line: p.order_line_id || null, p_units: num(p.units), p_defect: s(p.defect_type), p_cause: s(p.cause), p_outcome: s(p.outcome) || 'redo', p_movement: s(p.movement) || null, p_notes: s(p.notes) || null, p_actor: actor }, 'Rework job opened.');
  case 'rework':
    if (!p.id) return bad('Choose a rework job.');
    if (!['start', 'assign', 'complete', 'cancel', 'replacement'].includes(s(p.step))) return bad('Unknown rework step.');
    if (s(p.step) === 'replacement' && s(p.payload && p.payload.status) === 'not_needed' && !senior) return bad('Only a manager or admin can decide that no replacement is needed.', 403);
    if (s(p.step) === 'complete' && p.payload && p.payload.no_replacement && !senior) return bad('Only a manager or admin can decide that scrapped units need no replacement.', 403);
    return ok('flow_qc_rework_update', { p_id: p.id, p_action: s(p.step), p_payload: p.payload || {}, p_actor: actor }, 'Rework updated.');
  case 'set_criterion':
    if (!senior) return bad('Only a manager or admin can change the quality checklist.', 403);
    return ok('flow_qc_criterion_save', { p: { id: p.id || null, method: s(p.method) || null, name: s(p.name), description: s(p.description) || null, gates: Array.isArray(p.gates) ? p.gates : [], required: p.required !== false, critical: p.critical === true, needs_photo: p.needs_photo === true, active: p.active !== false, sort_order: p.sort_order == null ? null : p.sort_order }, p_actor: actor }, 'Checklist updated.');
  case 'confirm_checklist':
    if (!senior) return bad('Only a manager or admin can confirm the quality checklist.', 403);
    return ok('flow_qc_confirm_checklist', { p_note: s(p.note) || null, p_actor: actor }, 'Checklist confirmed.');
  default:
    return bad('Unknown action.');
}
